import {FlightGame,AIRCRAFT,UPGRADES} from './game.js';
const $=id=>document.getElementById(id), fmt=n=>String(Math.floor(n||0)).padStart(6,'0');
const MEDALS=[['first','初次出击'],['ace','王牌连击'],['rings','穿云而过'],['dodge','燕返高手'],['boss','海盗克星'],['score','天空传奇']];
const defaults={best:0,coins:0,unlocked:[0],selected:0,medals:[],difficulty:'adventure',control:'keyboard',sound:true};
let saved;try{saved=JSON.parse(localStorage.getItem('swallow-skies-v1')||'null');}catch{}
const profile={...defaults,...(saved&&typeof saved==='object'?saved:{})};profile.best=Number.isFinite(profile.best)?Math.max(0,profile.best):0;profile.coins=Number.isFinite(profile.coins)?Math.max(0,profile.coins):0;profile.unlocked=Array.isArray(profile.unlocked)?[...new Set([0,...profile.unlocked.filter(i=>[0,1,2].includes(i))])]:[0];profile.medals=Array.isArray(profile.medals)?profile.medals.filter(x=>MEDALS.some(m=>m[0]===x)):[];if(!profile.unlocked.includes(profile.selected))profile.selected=0;const save=()=>{try{localStorage.setItem('swallow-skies-v1',JSON.stringify(profile));}catch{}};
export let game;
try{game=new FlightGame($('world'));}catch(error){$('loading').innerHTML='<span class="brand-mark">✦</span><strong>你的浏览器暂时无法起飞</strong><span>请开启浏览器硬件加速，或换用支持 WebGL 的浏览器。</span><button class="secondary" onclick="location.reload()">再试一次</button>';throw error;}
game.control=profile.control==='mouse'?'mouse':'keyboard';game.audio.enabled=profile.sound!==false;game.selectPlane(profile.selected);$('loading').hidden=true;
let dialogType='',focusReturn=null,toastTimeout,radioTimeout,lastUI=0,boundaryNotice=0,finishData=null,firstStart=true;const mobile=matchMedia('(pointer: coarse)').matches||innerWidth<700;if(mobile)document.body.classList.add('touch');
function refreshMenu(){$('best-score').textContent=fmt(profile.best);$('medal-count').textContent=`${profile.medals.length} / 6`;$('menu-plane-name').textContent=AIRCRAFT[game.selected].name;$('difficulty-btn').textContent=`难度：${profile.difficulty==='ace'?'王牌飞行员':'冒险家'} ⌄`;$('control-btn').textContent=`操纵：${mobile?'触屏摇杆':game.control==='mouse'?'鼠标':'键盘'} ⌄`;$('sound-btn').textContent=game.audio.enabled?'♪':'♫̸';$('sound-btn').setAttribute('aria-label',game.audio.enabled?'关闭声音':'开启声音');}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.remove('show'),2400);}
function radio(text){$('radio-text').textContent=text;clearTimeout(radioTimeout);radioTimeout=setTimeout(()=>{$('radio-text').textContent=game.waveBoss?'黑帆舰长就在前面！保持机动。':game.wave>1?'收集补给，记得用翻滚避开敌人的炮火。':'跟着雷达寻找敌机，保持机动。';},6500);}
function showDialog(type,html){focusReturn=document.activeElement;dialogType=type;$('dialog').innerHTML=html;$('dialog-layer').hidden=false;queueMicrotask(()=>($('dialog').querySelector('button')||$('dialog')).focus());}
function closeDialog(){dialogType='';$('dialog-layer').hidden=true;if(focusReturn?.isConnected)focusReturn.focus();}
function leaveToMenu(){if(game.mode==='paused'||game.mode==='upgrade')settle({won:false,score:game.score,kills:game.kills,rings:game.ringTotal,coins:game.runCoins,stats:game.stats});closeDialog();game.menu();refreshMenu();}
function start(){closeDialog();finishData=null;game.start(profile.difficulty==='ace'?'ace':'adventure');document.activeElement?.blur();}
$('start-btn').onclick=start;
$('difficulty-btn').onclick=()=>{profile.difficulty=profile.difficulty==='ace'?'adventure':'ace';save();refreshMenu();};
$('control-btn').onclick=()=>{if(mobile){manual();return;}game.control=game.control==='keyboard'?'mouse':'keyboard';profile.control=game.control;save();refreshMenu();};
function toggleSound(){game.audio.init();game.audio.enabled=!game.audio.enabled;profile.sound=game.audio.enabled;save();refreshMenu();}
$('sound-btn').onclick=toggleSound;game.addEventListener('soundtoggle',toggleSound);
$('fullscreen-btn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('此浏览器暂不支持全屏');}};
addEventListener('keydown',e=>{if(e.code==='KeyF'&&!e.repeat)$('fullscreen-btn').click();if(e.code==='Escape'&&dialogType&&['manual','hangar'].includes(dialogType)){closeDialog();if(game.mode==='paused')game.resume();}if(e.code==='Tab'&&!$('dialog-layer').hidden){const focusable=[...$('dialog').querySelectorAll('button:not(:disabled),a,input,select')];if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.querySelector('.brand').onclick=e=>{e.preventDefault();if(game.mode==='playing')game.pause();else if(game.mode==='menu')closeDialog();};
function manual(){if(!['playing','paused','menu'].includes(game.mode))return;if(game.mode==='playing')game.pause();const active=game.mode==='paused';showDialog('manual',`<button class="close-dialog" aria-label="关闭">×</button><div class="eyebrow">FLIGHT MANUAL</div><h2 id="dialog-title">每个王牌，都有第一次起飞。</h2><p class="subtitle">飞机会自动向前飞行。先熟悉转向，再把海盗放进准星。</p><div class="manual-grid"><div><kbd>W / S</kbd><span>抬升 / 下降（方向键亦可）</span></div><div><kbd>A / D</kbd><span>向左 / 向右转向</span></div><div><kbd>SPACE / 鼠标</kbd><span>按住机枪射击</span></div><div><kbd>E</kbd><span>锁定后发射追踪导弹</span></div><div><kbd>Q</kbd><span>翻滚闪避 · 短暂无敌</span></div><div><kbd>SHIFT</kbd><span>按住加速 · 松开恢复能量</span></div><div><kbd>X</kbd><span>切换锁定目标自动开火</span></div><div><kbd>ESC / P</kbd><span>暂停 / 继续飞行</span></div></div><div class="tips">◎ 穿过金色航线环得分，集齐三个可获得额外奖励。<br>◈ 靠近彩色补给会自动吸取：绿色修复、蓝色护盾、金色导弹。<br>✦ 连续击落海盗可提升连击倍率；每波结束选择一项升级。<br>${mobile?'触屏：左侧摇杆操纵，右侧按钮开火；点击技能按钮使用技能。':'鼠标模式：移动鼠标控制机头，中心位置保持直飞；随时可以使用键盘修正。'}</div><div class="toggle-row"><button id="keyboard-choice" class="${game.control==='keyboard'?'selected':''}">键盘操纵</button><button id="mouse-choice" class="${game.control==='mouse'?'selected':''}">鼠标操纵</button></div><div class="dialog-actions"><button class="primary" id="manual-close">${active?'继续飞行':'准备好了'}</button></div>`);const end=()=>{closeDialog();if(active)game.resume();};$('dialog').querySelector('.close-dialog').onclick=end;$('manual-close').onclick=end;for(const control of['keyboard','mouse'])$(`${control}-choice`).onclick=()=>{game.control=control;profile.control=control;save();refreshMenu();for(const c of['keyboard','mouse'])$(`${c}-choice`).classList.toggle('selected',c===control);};}
$('help-btn').onclick=manual;$('guide-btn').onclick=manual;
function hangar(){showDialog('hangar',`<button class="close-dialog" aria-label="关闭机库">×</button><div class="eyebrow">THE HANGAR · 飞行补给点</div><h2 id="dialog-title">选择你的天空伙伴。</h2><p class="subtitle">你的飞行金币：<strong>${profile.coins}</strong>　·　击落海盗与完成航线获得金币</p><div class="aircraft-grid">${AIRCRAFT.map((a,i)=>`<button class="aircraft-card ${game.selected===i?'selected':''}" data-plane="${i}" ${!profile.unlocked.includes(i)&&profile.coins<a.cost?'disabled':''}><span class="card-symbol">${['✦','ϟ','◈'][i]}</span><h3>${a.name}</h3><p>${a.subtitle}</p><div class="specs">生命 ${a.hp}<br>巡航 ${Math.round(a.speed*1.4)} km/h<br>火力 ${['均衡','高速连发','稳健'][i]}</div><div class="plane-choice">${game.selected===i?'✓ 当前座驾':profile.unlocked.includes(i)?'选择这架飞机':`解锁 · ${a.cost} 金币`}</div></button>`).join('')}</div><div class="medals">${MEDALS.map(([id,name])=>`<span class="${profile.medals.includes(id)?'earned':''}">✧ ${name}</span>`).join('')}</div><p class="subtitle" style="font-size:11px;margin-top:18px;margin-bottom:0">战绩、解锁和金币仅保存在当前浏览器。</p><div class="dialog-actions"><button id="hangar-close" class="primary">返回停机坪</button></div>`);$('dialog').querySelector('.close-dialog').onclick=closeDialog;$('hangar-close').onclick=closeDialog;for(const btn of $('dialog').querySelectorAll('[data-plane]'))btn.onclick=()=>{const i=Number(btn.dataset.plane);if(!profile.unlocked.includes(i)){if(profile.coins<AIRCRAFT[i].cost)return;profile.coins-=AIRCRAFT[i].cost;profile.unlocked.push(i);}profile.selected=i;game.selectPlane(i);save();refreshMenu();hangar();};}
$('hangar-btn').onclick=hangar;
function pauseMenu(){showDialog('pause',`<div class="eyebrow">TAKE A BREATHER</div><h2 id="dialog-title">在云端，歇一会儿。</h2><p class="subtitle">你的冒险已暂停。天空会等你回来。</p><div class="stat-grid"><div><strong>${fmt(game.score)}</strong><small>当前得分</small></div><div><strong>${game.wave}</strong><small>当前波次</small></div><div><strong>${game.kills}</strong><small>击落海盗</small></div></div><div class="dialog-actions"><button class="primary" id="resume-btn">继续飞行</button><button class="secondary" id="paused-guide">飞行手册</button><button class="secondary" id="return-menu">返回停机坪</button></div>`);$('resume-btn').onclick=()=>game.resume();$('paused-guide').onclick=manual;$('return-menu').onclick=leaveToMenu;}
$('pause-btn').onclick=()=>game.pause();$('missile-btn').onclick=()=>game.missile();$('roll-btn').onclick=()=>game.roll();$('auto-btn').onclick=()=>{game.autoFire=!game.autoFire;};
$('boost-btn').onpointerdown=e=>{e.preventDefault();game.touch.boost=true;$('boost-btn').setPointerCapture(e.pointerId);};for(const type of['pointerup','pointercancel','lostpointercapture'])$('boost-btn').addEventListener(type,()=>game.touch.boost=false);
$('touch-fire').onpointerdown=e=>{e.preventDefault();game.touch.fire=true;game.audio.init();$('touch-fire').setPointerCapture(e.pointerId);};for(const type of['pointerup','pointercancel','lostpointercapture'])$('touch-fire').addEventListener(type,()=>game.touch.fire=false);
let stickPointer=null;const stick=$('joystick');function stickMove(e){const r=stick.getBoundingClientRect();const dx=(e.clientX-r.left-r.width/2)/32,dy=(e.clientY-r.top-r.height/2)/32;const len=Math.max(1,Math.hypot(dx,dy));game.touch.x=dx/len;game.touch.y=dy/len;stick.firstElementChild.style.transform=`translate(${game.touch.x*26}px,${game.touch.y*26}px)`;}
stick.onpointerdown=e=>{e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);stickMove(e);};stick.onpointermove=e=>{if(stickPointer===e.pointerId)stickMove(e);};for(const type of['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(type,()=>{stickPointer=null;game.touch.x=0;game.touch.y=0;stick.firstElementChild.style.transform='';});
game.addEventListener('start',()=>{document.body.classList.add('playing');$('menu').hidden=true;$('hud').hidden=false;radio('小燕，碧蓝群岛交给你了！空格开火，Q 翻滚。');if(firstStart){toast(mobile?'左侧摇杆操纵，右侧按钮开火':'WASD 操纵 · 空格射击 · X 自动开火');firstStart=false;}});
game.addEventListener('menu',()=>{document.body.classList.remove('playing');$('menu').hidden=false;$('hud').hidden=true;$('boss-hud').hidden=true;game.player.visible=true;refreshMenu();});
game.addEventListener('pause',pauseMenu);game.addEventListener('resume',closeDialog);game.addEventListener('toast',e=>toast(e.detail.text));game.addEventListener('radio',e=>radio(e.detail.text));game.addEventListener('boundary',e=>{if(performance.now()-boundaryNotice>7000){toast(e.detail.text);boundaryNotice=performance.now();}});
game.addEventListener('wave',e=>{const {wave,boss}=e.detail;$('wave-num').textContent=`${String(wave).padStart(2,'0')} / ${game.endless?'∞':'05'}`;$('wave-title').textContent=boss?'黑帆舰长，决战时刻':wave===1?'清空海盗巡逻队':['迎击海盗增援','截击海盗轰炸机','夺回群岛制空权'][(wave-2)%3];$('wave-banner').innerHTML=`<small>${boss?'PIRATE CAPTAIN INBOUND':'SWALLOW SQUADRON'}</small><strong>${boss?'黑帆舰长来袭':`第 ${wave} 波 · ${['碧海初航','海盗追击','云上交锋','群岛守卫'][(wave-1)%4]}`}</strong><span>${boss?'击破海盗飞艇，守护碧蓝群岛':'保持机动，守护这片天空'}</span>`;if(boss){radio('注意，巨型飞艇入侵！它的护航机和扇形弹幕很危险。');game.audio.play('alert');}else if(wave>1)radio('状态已整备，导弹补充 +2。下一批海盗就在前方。');});
game.addEventListener('upgrade',e=>{const {choices,wave}=e.detail;showDialog('upgrade',`<div class="eyebrow">WAVE ${String(wave).padStart(2,'0')} COMPLETE</div><h2 id="dialog-title">漂亮！让小飞机更强一点。</h2><p class="subtitle">选择一项空中补给，继续下一段冒险。战斗已暂停。</p><div class="upgrade-grid">${choices.map(u=>`<button class="upgrade-card" data-upgrade="${u.id}"><span class="card-symbol">${u.icon}</span><h3>${u.name}</h3><p>${u.text}</p><small>${u.tag}　＋</small></button>`).join('')}</div><div class="dialog-actions"><button class="secondary" id="upgrade-quit">保存战绩并返航</button></div>`);$('upgrade-quit').onclick=leaveToMenu;for(const b of $('dialog').querySelectorAll('[data-upgrade]'))b.onclick=()=>{if(game.mode!=='upgrade')return;game.upgrade(b.dataset.upgrade);closeDialog();};});
game.addEventListener('upgraded',e=>toast(`升级完成 · ${e.detail.name}`));
game.addEventListener('kill',()=>{if(game.combo===3)radio('漂亮的连击！继续保持！');});
game.addEventListener('damage',()=>{$('damage-flash').style.opacity='.55';setTimeout(()=>$('damage-flash').style.opacity='0',140);if(game.hp<game.maxHp*.3)radio('飞机受损，寻找绿色维修补给！翻滚可以避开炮火。');});
function settle(data){profile.best=Math.max(profile.best,data.score||0);profile.coins+=data.coins||0;game.runCoins=0;const earned=[];const unlock=(id,yes)=>{if(yes&&!profile.medals.includes(id)){profile.medals.push(id);earned.push(MEDALS.find(m=>m[0]===id)[1]);}};unlock('first',data.kills>0);unlock('ace',data.stats?.maxCombo>=5);unlock('rings',data.rings>=3);unlock('dodge',data.stats?.rolls>=5);unlock('boss',data.won);unlock('score',data.score>=5000);save();return earned;}
game.addEventListener('finish',e=>{finishData=e.detail;const d=finishData,earned=settle(d);showDialog('finish',`<div class="eyebrow">${d.won?'MISSION ACCOMPLISHED':'UNTIL NEXT FLIGHT'}</div><h2 id="dialog-title">${d.won?'这片天空，又属于我们了。':'每一次起飞，都更接近王牌。'}</h2><p class="subtitle">${d.won?'黑帆舰长已被击退。小燕，碧蓝群岛为你骄傲！':'小燕已安全跳伞。带上这次的经验，再来一次。'}</p><div class="stat-grid"><div><strong>${fmt(d.score)}</strong><small>本次得分</small></div><div><strong>${d.kills}</strong><small>击落海盗</small></div><div><strong>+${d.coins}</strong><small>飞行金币</small></div></div><div class="tips">飞行时间 ${Math.floor(d.time/60)} 分 ${Math.floor(d.time%60)} 秒　·　航线环 ${d.rings}　·　最高纪录 ${fmt(profile.best)}${earned.length?`<br>新徽章：${earned.join(' · ')}`:''}</div><div class="dialog-actions">${d.won?'<button class="primary" id="endless-btn">挑战无尽天空</button>':''}<button class="${d.won?'secondary':'primary'}" id="restart-btn">再次起飞</button><button class="secondary" id="finish-menu">返回停机坪</button></div>`);$('restart-btn').onclick=start;$('finish-menu').onclick=leaveToMenu;if(d.won)$('endless-btn').onclick=()=>{closeDialog();game.continueEndless();};refreshMenu();});
function radar(){const c=$('radar'),ctx=c.getContext('2d'),cx=80,cy=80;ctx.clearRect(0,0,160,160);ctx.strokeStyle='#accfc42b';ctx.lineWidth=1;for(const r of[25,50,73]){ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.stroke();}ctx.beginPath();ctx.moveTo(80,8);ctx.lineTo(80,152);ctx.moveTo(8,80);ctx.lineTo(152,80);ctx.stroke();const f=game.getForward(),right={x:-f.z,z:f.x};for(const e of game.enemies){if(e.hp<=0)continue;const dx=e.mesh.position.x-game.player.position.x,dz=e.mesh.position.z-game.player.position.z;let x=(dx*right.x+dz*right.z)*.075,y=-(dx*f.x+dz*f.z)*.075;const len=Math.hypot(x,y);if(len>69){x*=69/len;y*=69/len;}ctx.fillStyle=e.type===3?'#ffe4a2':'#f28b66';ctx.beginPath();ctx.arc(80+x,80+y,e.type===3?5:3,0,7);ctx.fill();}ctx.fillStyle='#ffeab5';ctx.beginPath();ctx.moveTo(80,72);ctx.lineTo(75,86);ctx.lineTo(80,83);ctx.lineTo(85,86);ctx.closePath();ctx.fill();}
function updateHUD(){if(!['playing','paused','upgrade','victory','gameover'].includes(game.mode))return;const now=performance.now();if(now-lastUI<55)return;lastUI=now;$('score').textContent=fmt(game.score);$('hp-text').textContent=`${Math.ceil(game.hp)} / ${game.maxHp}`;$('hp-bar').style.width=`${Math.max(0,game.hp/game.maxHp*100)}%`;$('shield-bar').style.width=`${game.shield/game.maxShield*100}%`;$('aircraft-name').textContent=AIRCRAFT[game.selected].name;$('combo').textContent=game.combo>1?`${game.combo} 连击 ×${Math.min(4,1+(game.combo-1)*.25).toFixed(2)}`:'';$('wave-objective').textContent=game.waveBoss?'击沉海盗旗舰':`击落敌机 ${Math.min(game.waveKills,game.waveTotal)} / ${game.waveTotal}`;$('wave-progress').style.width=`${Math.min(100,game.waveKills/game.waveTotal*100)}%`;$('ring-count').textContent=`${game.waveRings} / 3`;$('speed').innerHTML=`${Math.round(game.speed*1.4)}<small>KM/H</small>`;$('altitude').innerHTML=`${Math.round(game.player.position.y+85)}<small>ALT M</small>`;$('roll-status').textContent=game.rollCooldown>0?`${game.rollCooldown.toFixed(1)} s`:'READY';$('missile-count').textContent=`${game.missiles} 枚${game.target&&game.lockTime>.45?' · 已锁定':''}`;$('boost-bar').style.width=`${game.boost}%`;$('roll-btn').style.opacity=game.rollCooldown>0?'.65':'1';$('auto-btn').textContent=`自动开火 ${game.autoFire?'ON':'OFF'} [X]`;$('control-hint').textContent=game.control==='mouse'?'移动鼠标操纵 · 按住鼠标开火':'W S 俯仰 · A D 转向 · 空格射击';$('wave-banner').classList.toggle('show',game.bannerTimer>0&&game.mode==='playing');const boss=game.enemies.find(e=>e.type===3&&e.hp>0);$('boss-hud').hidden=!boss;if(boss)$('boss-health').style.width=`${Math.max(0,boss.hp/boss.maxHp*100)}%`;
 const mark=$('target-marker');if(game.target&&game.target.hp>0){const projected=game.target.mesh.position.clone().project(game.camera);const onScreen=projected.z<1&&Math.abs(projected.x)<1&&Math.abs(projected.y)<1;mark.hidden=!onScreen;mark.style.left=`${(projected.x+1)*innerWidth/2}px`;mark.style.top=`${(1-projected.y)*innerHeight/2}px`;mark.querySelector('span').textContent=game.lockTime>.45?'LOCKED':'LOCKING';mark.style.borderColor=game.lockTime>.45?'#ffdc86':'#fff9';}else mark.hidden=true;
 const arrow=$('edge-arrow');if(!game.target&&game.enemies.some(e=>e.hp>0)&&game.mode==='playing'){const e=game.enemies.find(e=>e.hp>0);const d=e.mesh.position.clone().sub(game.player.position);const f=game.getForward(),right={x:-f.z,z:f.x};const sideways=d.x*right.x+d.z*right.z,front=d.dot(f);const projected=e.mesh.position.clone().project(game.camera);if(front<0||Math.abs(projected.x)>.88||Math.abs(projected.y)>.75){arrow.hidden=false;arrow.style.left=sideways>0?'86%':'12%';arrow.style.top='45%';arrow.style.transform=`rotate(${sideways>0?90:-90}deg)`;}else arrow.hidden=true;}else arrow.hidden=true;radar();}
game.addEventListener('frame',updateHUD);
refreshMenu();
// The optional browser tool API shares the same actions and state as the controls.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_flight_status',description:'Read the current aircraft, mission, health, ammunition and score.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>game.state()});register({name:'set_flight_pause',description:'Pause or resume the current flight. No effect on the menu or upgrade choices.',inputSchema:{type:'object',properties:{paused:{type:'boolean'}},required:['paused'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(typeof input?.paused!=='boolean')throw Error('paused must be a boolean');if(!['playing','paused'].includes(game.mode))throw Error('No active flight');input.paused?game.pause():game.resume();return game.state();}});addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
